/** Get all teachers with user details */
export async function getAllTeachers() {
  const { data } = await supabase
    .from('teachers')
    .select(`
      *,
      user:users(id, cnic, first_name, last_name, email, phone, education, avatar_url, is_verified, created_at)
    `)
    .order('created_at', { ascending: false });
  return data || [];
}

/** Create teacher (creates user + teacher profile) */
export async function createTeacher(userData, teacherData) {
  const result = await createUser({ ...userData, role: 'teacher', is_verified: true });
  if (result.error) return result;

  const { data, error } = await supabase
    .from('teachers')
    .insert({
      id: result.user.id,
      employee_id: teacherData.employee_id,
      qualification: teacherData.qualification,
      specialization: teacherData.specialization,
      joining_date: teacherData.joining_date,
      status: 'active',
    })
    .select()
    .single();

  if (error) return { error: error.message };
  return { teacher: data, user: result.user };
}

/** Update teacher profile */
export async function updateTeacher(teacherId, updates) {
  const { data, error } = await supabase
    .from('teachers')
    .update(updates)
    .eq('id', teacherId)
    .select()
    .single();
  if (error) return { error: error.message };
  return { teacher: data };
}

