/** Create challan */
export async function createChallan(challanData) {
  // Generate challan number
  const { count } = await supabase
    .from('challans')
    .select('id', { count: 'exact', head: true });
  const challanNo = `CHN-${new Date().getFullYear()}-${String((count || 0) + 1).padStart(4, '0')}`;

  const { data, error } = await supabase
    .from('challans')
    .insert({ ...challanData, challan_no: challanNo })
    .select()
    .single();
  if (error) return { error: error.message };
  return { challan: data };
}

/** Submit challan payment */
export async function submitChallanPayment(paymentData) {
  // Insert payment record
  const { data: payment, error: payError } = await supabase
    .from('challan_payments')
    .insert(paymentData)
    .select()
    .single();
  if (payError) return { error: payError.message };

  // Update challan status
  await supabase
    .from('challans')
    .update({ status: 'pending_verification', updated_at: new Date().toISOString() })
    .eq('id', paymentData.challan_id);

  return { payment };
}

/** Approve/Reject challan payment */
export async function verifyChallanPayment(paymentId, challanId, status, verifiedBy, rejectionReason) {
  const { data, error } = await supabase
    .from('challan_payments')
    .update({
      status,
      verified_by: verifiedBy,
      verified_at: new Date().toISOString(),
      rejection_reason: rejectionReason || null,
    })
    .eq('id', paymentId)
    .select()
    .single();
  if (error) return { error: error.message };

  // Update challan status
  const challanStatus = status === 'approved' ? 'paid' : 'unpaid';
  await supabase
    .from('challans')
    .update({ status: challanStatus, updated_at: new Date().toISOString() })
    .eq('id', challanId);

  return { payment: data };
}

