/** Get attendance for a student */
export async function getStudentAttendance(studentId) {
  const { data } = await supabase
    .from('attendance_records')
    .select(`
      *,
      subject:class_subjects(subject_name, subject_code)
    `)
    .eq('student_id', studentId)
    .order('date', { ascending: false });
  return data || [];
}

/** Get attendance for a class on a date */
export async function getClassAttendance(classSubjectId, date) {
  const { data } = await supabase
    .from('attendance_records')
    .select(`
      *,
      student:students(id, first_name, last_name, roll_no)
    `)
    .eq('class_subject_id', classSubjectId)
    .eq('date', date)
    .order('student_id');
  return data || [];
}

/** Mark attendance (upsert) */
export async function markAttendance(records) {
  const { data, error } = await supabase
    .from('attendance_records')
    .upsert(records, { onConflict: 'student_id,class_subject_id,date' })
    .select();
  if (error) return { error: error.message };
  return { records: data };
}

/** Get attendance stats for a student */
export async function getStudentAttendanceStats(studentId) {
  const { data } = await supabase
    .from('attendance_records')
    .select('status')
    .eq('student_id', studentId);
  if (!data) return { total: 0, present: 0, absent: 0, leave: 0, percentage: 0 };
  const total = data.length;
  const present = data.filter(r => r.status === 'present').length;
  const absent = data.filter(r => r.status === 'absent').length;
  const leave = data.filter(r => r.status === 'leave').length;
  return {
    total,
    present,
    absent,
    leave,
    percentage: total > 0 ? ((present / total) * 100).toFixed(1) : 0,
  };
}

