// DASHBOARD STATS
// ============================================================

/** Get admin dashboard stats */
export async function getDashboardStats() {
  const [students, teachers, guardians, pendingAdmissions, pendingChallans, announcements] = await Promise.all([
    supabase.from('students').select('id', { count: 'exact', head: true }).eq('status', 'active'),
    supabase.from('teachers').select('id', { count: 'exact', head: true }).eq('status', 'active'),
    supabase.from('guardians').select('id', { count: 'exact', head: true }),
    supabase.from('admission_applications').select('id', { count: 'exact', head: true }).eq('status', 'pending'),
    supabase.from('challans').select('id', { count: 'exact', head: true }).eq('status', 'pending_verification'),
    supabase.from('announcements').select('id', { count: 'exact', head: true }),
  ]);

  return {
    totalStudents: students.count || 0,
    totalTeachers: teachers.count || 0,
    totalGuardians: guardians.count || 0,
    pendingAdmissions: pendingAdmissions.count || 0,
    pendingChallans: pendingChallans.count || 0,
    totalAnnouncements: announcements.count || 0,
  };
}

/** Search across entities (admin mega search) */
export async function globalSearch(query) {
  const searchTerm = `%${query}%`;
  const [students, teachers, guardians] = await Promise.all([
    supabase.from('students').select('id, roll_no, first_name, last_name').or(`first_name.ilike.${searchTerm},last_name.ilike.${searchTerm},roll_no.ilike.${searchTerm}`).limit(5),
    supabase.from('users').select('id, cnic, first_name, last_name, role').eq('role', 'teacher').or(`first_name.ilike.${searchTerm},last_name.ilike.${searchTerm},cnic.ilike.${searchTerm}`).limit(5),
    supabase.from('users').select('id, cnic, first_name, last_name, role').eq('role', 'guardian').or(`first_name.ilike.${searchTerm},last_name.ilike.${searchTerm},cnic.ilike.${searchTerm}`).limit(5),
  ]);

  return {
    students: students.data || [],
    teachers: teachers.data || [],
    guardians: guardians.data || [],
  };
}

