const Card = ({ children, style, onClick }) => (
  <div onClick={onClick} style={{
    background: 'rgba(255,255,255,0.03)',
    border: '1px solid rgba(255,255,255,0.06)',
    borderRadius: 16,
    padding: 24,
    transition: 'all 0.3s ease',
    ...style,
  }}>
    {children}
  </div>
);

const StatCard = ({ label, value, icon, color }) => (
  <Card style={{ display: 'flex', alignItems: 'center', gap: 16, cursor: 'default' }}>
    <div style={{
      width: 48, height: 48, borderRadius: 14,
      background: `${color}15`,
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      flexShrink: 0,
    }}>
      {icon(22, color)}
    </div>
    <div>
      <div style={{ fontSize: '1.6rem', fontWeight: 800, color: '#fff', lineHeight: 1 }}>{value}</div>
      <div style={{ fontSize: '0.78rem', color: 'rgba(255,255,255,0.4)', marginTop: 4, fontWeight: 500 }}>{label}</div>
    </div>
  </Card>
);

const Button = ({ children, onClick, variant = 'primary', style, disabled }) => {
  const baseStyle = {
    padding: '10px 20px',
    borderRadius: 12,
    fontSize: '0.82rem',
    fontWeight: 600,
    cursor: disabled ? 'not-allowed' : 'pointer',
    transition: 'all 0.2s ease',
    display: 'inline-flex',
    alignItems: 'center',
    gap: 8,
    border: 'none',
    opacity: disabled ? 0.5 : 1,
  };
  const variants = {
    primary: { background: `linear-gradient(135deg, ${GOLD}, #e09800)`, color: '#0a0e1a' },
    secondary: { background: 'rgba(255,255,255,0.06)', color: '#fff', border: '1px solid rgba(255,255,255,0.1)' },
    danger: { background: 'rgba(239,68,68,0.15)', color: '#fca5a5', border: '1px solid rgba(239,68,68,0.2)' },
    success: { background: 'rgba(34,197,94,0.15)', color: '#86efac', border: '1px solid rgba(34,197,94,0.2)' },
  };
  return (
    <button onClick={disabled ? undefined : onClick} style={{ ...baseStyle, ...variants[variant], ...style }}>{children}</button>
  );
};

