// SECTION: DASHBOARD
// ============================================================
function DashboardSection() {
  const [stats, setStats] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState(null);
  const [searching, setSearching] = useState(false);

  useEffect(() => {
    db.getDashboardStats().then(setStats);
  }, []);

  useEffect(() => {
    if (!searchQuery.trim()) { setSearchResults(null); return; }
    const t = setTimeout(async () => {
      setSearching(true);
      const results = await db.globalSearch(searchQuery);
      setSearchResults(results);
      setSearching(false);
    }, 400);
    return () => clearTimeout(t);
  }, [searchQuery]);

  return (
    <div>
      {/* Mega Search */}
      <div style={{ position: 'relative', marginBottom: 32 }}>
        <div style={{
          display: 'flex', alignItems: 'center', gap: 12,
          background: 'rgba(255,255,255,0.04)',
          border: '1px solid rgba(255,255,255,0.1)',
          borderRadius: 16, padding: '14px 20px',
        }}>
          {Icons.search(20, 'rgba(255,255,255,0.3)')}
          <input
            value={searchQuery}
            onChange={e => setSearchQuery(e.target.value)}
            placeholder="Search students, teachers, guardians by name, CNIC, or roll number..."
            style={{
              flex: 1, background: 'none', border: 'none', outline: 'none',
              color: '#fff', fontSize: '0.92rem',
            }}
          />
          {searching && <div style={{ width: 18, height: 18, border: '2px solid rgba(255,255,255,0.1)', borderTopColor: GOLD, borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />}
        </div>
        {searchResults && (
          <div style={{
            position: 'absolute', top: '100%', left: 0, right: 0, marginTop: 8,
            background: '#1a1f2e', border: '1px solid rgba(255,255,255,0.1)',
            borderRadius: 14, padding: 16, zIndex: 100,
            boxShadow: '0 20px 60px rgba(0,0,0,0.4)',
            maxHeight: 320, overflow: 'auto',
          }}>
            {['students', 'teachers', 'guardians'].map(cat => (
              searchResults[cat]?.length > 0 && (
                <div key={cat} style={{ marginBottom: 12 }}>
                  <div style={{ fontSize: '0.7rem', fontWeight: 700, color: GOLD, textTransform: 'uppercase', marginBottom: 6, letterSpacing: '0.1em' }}>{cat}</div>
                  {searchResults[cat].map(item => (
                    <div key={item.id} style={{ padding: '8px 12px', borderRadius: 8, cursor: 'pointer', fontSize: '0.85rem', color: '#e2e8f0', transition: 'background 0.15s' }} onMouseEnter={e => e.currentTarget.style.background = 'rgba(255,255,255,0.05)'} onMouseLeave={e => e.currentTarget.style.background = 'transparent'}>
                      {item.first_name} {item.last_name} {item.roll_no && <span style={{ color: 'rgba(255,255,255,0.3)', marginLeft: 8 }}>{item.roll_no}</span>} {item.cnic && <span style={{ color: 'rgba(255,255,255,0.25)', marginLeft: 8 }}>{item.cnic}</span>}
                    </div>
                  ))}
                </div>
              )
            ))}
            {searchResults.students?.length === 0 && searchResults.teachers?.length === 0 && searchResults.guardians?.length === 0 && (
              <div style={{ textAlign: 'center', color: 'rgba(255,255,255,0.3)', padding: 20, fontSize: '0.85rem' }}>No results found</div>
            )}
          </div>
        )}
      </div>

      {/* Stat Cards */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))', gap: 16, marginBottom: 32 }}>
        <StatCard label="Total Students" value={stats?.totalStudents ?? '—'} icon={Icons.student} color="#3b82f6" />
        <StatCard label="Total Teachers" value={stats?.totalTeachers ?? '—'} icon={Icons.teacher} color={GOLD} />
        <StatCard label="Total Guardians" value={stats?.totalGuardians ?? '—'} icon={Icons.guardian} color="#8b5cf6" />
        <StatCard label="Pending Admissions" value={stats?.pendingAdmissions ?? '—'} icon={Icons.admission} color="#f97316" />
        <StatCard label="Pending Challans" value={stats?.pendingChallans ?? '—'} icon={Icons.challan} color="#ef4444" />
        <StatCard label="Announcements" value={stats?.totalAnnouncements ?? '—'} icon={Icons.announcement} color="#22c55e" />
      </div>
    </div>
  );
}

