function TeachersSection() {
  const [teachers, setTeachers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [formData, setFormData] = useState({ cnic: '', password: '', first_name: '', last_name: '', email: '', phone: '', education: '', employee_id: '', qualification: '', specialization: '', joining_date: '' });
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState('');

  const loadTeachers = async () => {
    setLoading(true);
    const data = await db.getAllTeachers();
    setTeachers(data);
    setLoading(false);
  };

  useEffect(() => { loadTeachers(); }, []);

  const handleCreate = async () => {
    setSaving(true); setMsg('');
    const result = await db.createTeacher(
      { cnic: formData.cnic, password: formData.password, first_name: formData.first_name, last_name: formData.last_name, email: formData.email, phone: formData.phone, education: formData.education },
      { employee_id: formData.employee_id, qualification: formData.qualification, specialization: formData.specialization, joining_date: formData.joining_date }
    );
    if (result.error) { setMsg(result.error); setSaving(false); return; }
    setShowModal(false);
    setFormData({ cnic: '', password: '', first_name: '', last_name: '', email: '', phone: '', education: '', employee_id: '', qualification: '', specialization: '', joining_date: '' });
    loadTeachers();
    setSaving(false);
  };

  const columns = [
    { key: 'employee_id', label: 'ID', nowrap: true },
    { key: 'name', label: 'Name', render: r => `${r.user?.first_name || ''} ${r.user?.last_name || ''}` },
    { key: 'cnic', label: 'CNIC', render: r => r.user?.cnic, nowrap: true },
    { key: 'specialization', label: 'Specialization' },
    { key: 'qualification', label: 'Qualification' },
    { key: 'status', label: 'Status', render: r => <Badge text={r.status} color={r.status === 'active' ? '#22c55e' : '#ef4444'} /> },
  ];

  return (
    <div>
      <SectionHeader title="Teachers" subtitle={`${teachers.length} registered teachers`} action={
        <Button onClick={() => setShowModal(true)}>{Icons.plus(16)} Create Teacher Account</Button>
      } />
      {loading ? <div style={{ textAlign: 'center', padding: 40, color: 'rgba(255,255,255,0.3)' }}>Loading...</div> :
        <Table columns={columns} data={teachers} actions={row => (
          <>
            <ActionButton icon={Icons.eye(14)} title="View" color={GOLD} />
            <ActionButton icon={Icons.edit(14)} title="Edit" color="#3b82f6" />
          </>
        )} />
      }
      {showModal && (
        <Modal title="Create Teacher Account" onClose={() => setShowModal(false)} width={600}>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0 16px' }}>
            <InputField label="First Name" value={formData.first_name} onChange={e => setFormData(p => ({...p, first_name: e.target.value}))} required />
            <InputField label="Last Name" value={formData.last_name} onChange={e => setFormData(p => ({...p, last_name: e.target.value}))} required />
            <InputField label="CNIC" value={formData.cnic} onChange={e => setFormData(p => ({...p, cnic: e.target.value}))} placeholder="35202-1234567-1" required />
            <InputField label="Password" value={formData.password} onChange={e => setFormData(p => ({...p, password: e.target.value}))} type="password" required />
            <InputField label="Email" value={formData.email} onChange={e => setFormData(p => ({...p, email: e.target.value}))} type="email" />
            <InputField label="Phone" value={formData.phone} onChange={e => setFormData(p => ({...p, phone: e.target.value}))} />
            <InputField label="Employee ID" value={formData.employee_id} onChange={e => setFormData(p => ({...p, employee_id: e.target.value}))} placeholder="EMP-008" required />
            <InputField label="Qualification" value={formData.qualification} onChange={e => setFormData(p => ({...p, qualification: e.target.value}))} />
            <InputField label="Specialization" value={formData.specialization} onChange={e => setFormData(p => ({...p, specialization: e.target.value}))} />
            <InputField label="Joining Date" value={formData.joining_date} onChange={e => setFormData(p => ({...p, joining_date: e.target.value}))} type="date" />
            <InputField label="Education" value={formData.education} onChange={e => setFormData(p => ({...p, education: e.target.value}))} />
          </div>
          {msg && <div style={{ color: '#ef4444', fontSize: '0.82rem', marginBottom: 12 }}>{msg}</div>}
          <div style={{ display: 'flex', gap: 12, justifyContent: 'flex-end', marginTop: 8 }}>
            <Button variant="secondary" onClick={() => setShowModal(false)}>Cancel</Button>
            <Button onClick={handleCreate} disabled={saving}>{saving ? 'Creating...' : 'Create Teacher'}</Button>
          </div>
        </Modal>
      )}
    </div>
  );
}

// ============================================================
// SECTION: SESSIONS & CLASSES
// ============================================================
function SessionsSection() {
  const [sessions, setSessions] = useState([]);
  const [classes, setClasses] = useState([]);
  const [courses, setCourses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [expandedSession, setExpandedSession] = useState(null);
  const [showCreateSession, setShowCreateSession] = useState(false);
  const [sessionForm, setSessionForm] = useState({ name: '', start_date: '', end_date: '', fee_structure: '{}' });
  const [saving, setSaving] = useState(false);

  const load = async () => {
    setLoading(true);
    const [s, cl, co] = await Promise.all([db.getAllSessions(), db.getAllClasses(), db.getAllCourses()]);
    setSessions(s); setClasses(cl); setCourses(co);
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  const handleCreateSession = async () => {
    setSaving(true);
    let feeStruct = {};
    try { feeStruct = JSON.parse(sessionForm.fee_structure); } catch {}
    await db.createSession({ name: sessionForm.name, start_date: sessionForm.start_date, end_date: sessionForm.end_date, fee_structure: feeStruct });
    setShowCreateSession(false);
    setSessionForm({ name: '', start_date: '', end_date: '', fee_structure: '{}' });
    load();
    setSaving(false);
  };

  if (loading) return <div style={{ textAlign: 'center', padding: 40, color: 'rgba(255,255,255,0.3)' }}>Loading...</div>;

  return (
    <div>
      <SectionHeader title="Sessions & Classes" subtitle={`${sessions.length} sessions, ${classes.length} classes, ${courses.length} courses`} action={
        <Button onClick={() => setShowCreateSession(true)}>{Icons.plus(16)} New Session</Button>
      } />

      {sessions.map(session => {
        const sessionClasses = classes.filter(c => c.session?.name === session.name);
        const sessionCourses = courses.filter(c => c.session?.name === session.name);
        const isExpanded = expandedSession === session.id;
        return (
          <Card key={session.id} style={{ marginBottom: 16, cursor: 'pointer' }} onClick={() => setExpandedSession(isExpanded ? null : session.id)}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                <div style={{ width: 40, height: 40, borderRadius: 12, background: `${GOLD}15`, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  {Icons.calendar(20, GOLD)}
                </div>
                <div>
                  <div style={{ fontWeight: 700, color: '#fff', fontSize: '1rem' }}>{session.name}</div>
                  <div style={{ fontSize: '0.75rem', color: 'rgba(255,255,255,0.4)' }}>
                    {session.start_date} — {session.end_date || 'Ongoing'} &nbsp;
                    <Badge text={session.is_active ? 'Active' : 'Inactive'} color={session.is_active ? '#22c55e' : '#6b7280'} />
                  </div>
                </div>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
                <span style={{ fontSize: '0.78rem', color: 'rgba(255,255,255,0.3)' }}>{sessionCourses.length} courses, {sessionClasses.length} classes</span>
                <div style={{ transform: isExpanded ? 'rotate(180deg)' : 'none', transition: 'transform 0.2s' }}>{Icons.chevronDown(16, 'rgba(255,255,255,0.3)')}</div>
              </div>
            </div>
            {isExpanded && (
              <div style={{ marginTop: 20, paddingTop: 16, borderTop: '1px solid rgba(255,255,255,0.06)' }} onClick={e => e.stopPropagation()}>
                {session.fee_structure && typeof session.fee_structure === 'object' && (
                  <div style={{ marginBottom: 16 }}>
                    <div style={{ fontSize: '0.75rem', fontWeight: 700, color: GOLD, textTransform: 'uppercase', marginBottom: 8, letterSpacing: '0.1em' }}>Fee Structure</div>
                    <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
                      {Object.entries(session.fee_structure).map(([k, v]) => (
                        <div key={k} style={{ padding: '6px 12px', background: 'rgba(255,255,255,0.04)', borderRadius: 8, fontSize: '0.78rem' }}>
                          <span style={{ color: 'rgba(255,255,255,0.5)', textTransform: 'capitalize' }}>{k.replace('_', ' ')}: </span>
                          <span style={{ color: '#fff', fontWeight: 600 }}>Rs. {Number(v).toLocaleString()}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
                <div style={{ fontSize: '0.75rem', fontWeight: 700, color: GOLD, textTransform: 'uppercase', marginBottom: 8, letterSpacing: '0.1em' }}>Courses</div>
                <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 16 }}>
                  {sessionCourses.map(c => <Badge key={c.id} text={`${c.course_code} — ${c.course_name}`} color="#3b82f6" />)}
                </div>
                <div style={{ fontSize: '0.75rem', fontWeight: 700, color: GOLD, textTransform: 'uppercase', marginBottom: 8, letterSpacing: '0.1em' }}>Classes</div>
                <Table
                  columns={[
                    { key: 'class_name', label: 'Class' },
                    { key: 'section', label: 'Section' },
                    { key: 'semester', label: 'Semester' },
                    { key: 'course', label: 'Course', render: r => r.course?.course_code },
                    { key: 'incharge', label: 'Incharge Teacher', render: r => r.incharge?.user ? `${r.incharge.user.first_name} ${r.incharge.user.last_name}` : 'Not Assigned' },
                    { key: 'max_students', label: 'Max Students' },
                  ]}
                  data={sessionClasses}
                />
              </div>
            )}
          </Card>
        );
      })}

      {showCreateSession && (
        <Modal title="Create New Session" onClose={() => setShowCreateSession(false)}>
          <InputField label="Session Name" value={sessionForm.name} onChange={e => setSessionForm(p => ({...p, name: e.target.value}))} placeholder="e.g. Spring 2027" required />
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0 16px' }}>
            <InputField label="Start Date" value={sessionForm.start_date} onChange={e => setSessionForm(p => ({...p, start_date: e.target.value}))} type="date" required />
            <InputField label="End Date" value={sessionForm.end_date} onChange={e => setSessionForm(p => ({...p, end_date: e.target.value}))} type="date" />
          </div>
          <InputField label="Fee Structure (JSON)" value={sessionForm.fee_structure} onChange={e => setSessionForm(p => ({...p, fee_structure: e.target.value}))} placeholder='{"tuition": 45000, "lab_fee": 5000}' />
          <div style={{ display: 'flex', gap: 12, justifyContent: 'flex-end', marginTop: 8 }}>
            <Button variant="secondary" onClick={() => setShowCreateSession(false)}>Cancel</Button>
            <Button onClick={handleCreateSession} disabled={saving}>{saving ? 'Creating...' : 'Create Session'}</Button>
          </div>
        </Modal>
      )}
    </div>
  );
}

