// SECTION: ADMISSIONS
// ============================================================
function AdmissionsSection() {
  const [admissions, setAdmissions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedApp, setSelectedApp] = useState(null);
  const [adminNotes, setAdminNotes] = useState('');
  const [saving, setSaving] = useState(false);

  const load = async () => {
    setLoading(true);
    setAdmissions(await db.getAllAdmissions());
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  const handleAction = async (status) => {
    setSaving(true);
    const user = getCurrentUser();
    await db.updateAdmission(selectedApp.id, { status, admin_notes: adminNotes, reviewed_by: user?.id });
    setSelectedApp(null);
    setAdminNotes('');
    load();
    setSaving(false);
  };

  const columns = [
    { key: 'student', label: 'Student Name', render: r => `${r.student_first_name} ${r.student_last_name}` },
    { key: 'guardian', label: 'Guardian', render: r => r.guardian?.user ? `${r.guardian.user.first_name} ${r.guardian.user.last_name}` : '—' },
    { key: 'desired_course', label: 'Course' },
    { key: 'session', label: 'Session', render: r => r.session?.name || '—' },
    { key: 'previous_school', label: 'Previous School' },
    { key: 'status', label: 'Status', render: r => <Badge text={r.status} color={r.status === 'pending' ? '#f97316' : r.status === 'approved' ? '#22c55e' : '#ef4444'} /> },
    { key: 'created_at', label: 'Applied', render: r => new Date(r.created_at).toLocaleDateString(), nowrap: true },
  ];

  return (
    <div>
      <SectionHeader title="Admission Applications" subtitle={`${admissions.filter(a => a.status === 'pending').length} pending applications`} />
      {loading ? <div style={{ textAlign: 'center', padding: 40, color: 'rgba(255,255,255,0.3)' }}>Loading...</div> :
        <Table columns={columns} data={admissions} actions={row => row.status === 'pending' ? (
          <>
            <ActionButton icon={Icons.check(14)} title="Approve" color="#22c55e" onClick={() => { setSelectedApp(row); setAdminNotes(''); }} />
            <ActionButton icon={Icons.x(14)} title="Reject" color="#ef4444" onClick={() => { setSelectedApp(row); setAdminNotes(''); }} />
          </>
        ) : (
          <ActionButton icon={Icons.eye(14)} title="View" color={GOLD} onClick={() => setSelectedApp(row)} />
        )} />
      }
      {selectedApp && (
        <Modal title={`Application: ${selectedApp.student_first_name} ${selectedApp.student_last_name}`} onClose={() => setSelectedApp(null)} width={560}>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12, marginBottom: 16 }}>
            {[
              ['Student Name', `${selectedApp.student_first_name} ${selectedApp.student_last_name}`],
              ['Gender', selectedApp.student_gender],
              ['DOB', selectedApp.student_dob],
              ['B-Form', selectedApp.student_b_form || '—'],
              ['Course', selectedApp.desired_course],
              ['Previous School', selectedApp.previous_school || '—'],
              ['Previous Grade', selectedApp.previous_grade || '—'],
              ['Guardian', selectedApp.guardian?.user ? `${selectedApp.guardian.user.first_name} ${selectedApp.guardian.user.last_name}` : '—'],
              ['Guardian CNIC', selectedApp.guardian?.user?.cnic || '—'],
              ['Guardian Phone', selectedApp.guardian?.user?.phone || '—'],
            ].map(([l, v]) => (
              <div key={l}>
                <div style={{ fontSize: '0.7rem', color: 'rgba(255,255,255,0.4)', fontWeight: 600, textTransform: 'uppercase' }}>{l}</div>
                <div style={{ fontSize: '0.88rem', color: '#fff', marginTop: 2 }}>{v}</div>
              </div>
            ))}
          </div>
          {selectedApp.status === 'pending' && (
            <>
              <div style={{ marginBottom: 14 }}>
                <label style={{ display: 'block', fontSize: '0.78rem', color: 'rgba(255,255,255,0.5)', marginBottom: 6, fontWeight: 500 }}>Admin Notes</label>
                <textarea value={adminNotes} onChange={e => setAdminNotes(e.target.value)} rows={3} placeholder="Add notes about this application..." style={{
                  width: '100%', padding: '10px 14px', background: 'rgba(255,255,255,0.04)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 10, color: '#fff', fontSize: '0.85rem', outline: 'none', resize: 'vertical', fontFamily: 'inherit',
                }} />
              </div>
              <div style={{ display: 'flex', gap: 12, justifyContent: 'flex-end' }}>
                <Button variant="danger" onClick={() => handleAction('rejected')} disabled={saving}>Reject</Button>
                <Button variant="success" onClick={() => handleAction('approved')} disabled={saving}>Approve</Button>
              </div>
            </>
          )}
          {selectedApp.status !== 'pending' && selectedApp.admin_notes && (
            <div style={{ padding: 12, background: 'rgba(255,255,255,0.04)', borderRadius: 10, fontSize: '0.82rem', color: 'rgba(255,255,255,0.6)' }}>
              <strong>Admin Notes:</strong> {selectedApp.admin_notes}
            </div>
          )}
        </Modal>
      )}
    </div>
  );
}

// ============================================================
// SECTION: CHALLANS
// ============================================================
function ChallansSection() {
  const [challans, setChallans] = useState([]);
  const [pendingPayments, setPendingPayments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState('all');
  const [showCreate, setShowCreate] = useState(false);
  const [students, setStudents] = useState([]);
  const [form, setForm] = useState({ student_id: '', title: '', amount: '', due_date: '', month: '', description: '' });
  const [saving, setSaving] = useState(false);
  const [reviewingPayment, setReviewingPayment] = useState(null);

  const load = async () => {
    setLoading(true);
    const [all, pending, studs] = await Promise.all([db.getAllChallans(), db.getPendingChallans(), db.getAllStudents()]);
    setChallans(all); setPendingPayments(pending); setStudents(studs);
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  const handleCreate = async () => {
    setSaving(true);
    const user = getCurrentUser();
    await db.createChallan({ ...form, amount: parseFloat(form.amount), created_by: user?.id });
    setShowCreate(false);
    setForm({ student_id: '', title: '', amount: '', due_date: '', month: '', description: '' });
    load();
    setSaving(false);
  };

  const handleVerify = async (status) => {
    setSaving(true);
    const user = getCurrentUser();
    const payment = reviewingPayment.payment?.[0];
    if (payment) {
      await db.verifyChallanPayment(payment.id, reviewingPayment.id, status, user?.id);
    }
    setReviewingPayment(null);
    load();
    setSaving(false);
  };

  const challanColumns = [
    { key: 'challan_no', label: 'Challan No', nowrap: true },
    { key: 'student', label: 'Student', render: r => r.student ? `${r.student.first_name} ${r.student.last_name}` : '—' },
    { key: 'roll', label: 'Roll No', render: r => r.student?.roll_no || '—', nowrap: true },
    { key: 'title', label: 'Title' },
    { key: 'amount', label: 'Amount', render: r => `Rs. ${Number(r.amount).toLocaleString()}`, nowrap: true },
    { key: 'due_date', label: 'Due Date', nowrap: true },
    { key: 'status', label: 'Status', render: r => <Badge text={r.status?.replace('_', ' ')} color={
      r.status === 'paid' ? '#22c55e' : r.status === 'pending_verification' ? '#f97316' : r.status === 'overdue' ? '#ef4444' : '#6b7280'
    } /> },
  ];

  const displayData = tab === 'pending' ? pendingPayments : challans;

  return (
    <div>
      <SectionHeader title="Challans" subtitle={`${pendingPayments.length} pending verification`} action={
        <Button onClick={() => setShowCreate(true)}>{Icons.plus(16)} New Challan</Button>
      } />

      {/* Tabs */}
      <div style={{ display: 'flex', gap: 4, marginBottom: 20, background: 'rgba(255,255,255,0.03)', borderRadius: 12, padding: 4, width: 'fit-content' }}>
        {[{ id: 'all', label: 'All Challans' }, { id: 'pending', label: `Pending Approvals (${pendingPayments.length})` }].map(t => (
          <button key={t.id} onClick={() => setTab(t.id)} style={{
            padding: '8px 18px', borderRadius: 10, border: 'none', cursor: 'pointer', fontSize: '0.82rem', fontWeight: 600, transition: 'all 0.2s',
            background: tab === t.id ? `${GOLD}20` : 'transparent',
            color: tab === t.id ? GOLD : 'rgba(255,255,255,0.4)',
          }}>{t.label}</button>
        ))}
      </div>

      {loading ? <div style={{ textAlign: 'center', padding: 40, color: 'rgba(255,255,255,0.3)' }}>Loading...</div> :
        <Table columns={challanColumns} data={displayData} actions={row => {
          if (row.status === 'pending_verification' && row.payment?.[0]) {
            return (
              <Button variant="primary" onClick={() => setReviewingPayment(row)} style={{ padding: '6px 14px', fontSize: '0.75rem' }}>Review</Button>
            );
          }
          return <ActionButton icon={Icons.eye(14)} title="View" color={GOLD} />;
        }} />
      }

      {/* Create Challan Modal */}
      {showCreate && (
        <Modal title="Create New Challan" onClose={() => setShowCreate(false)}>
          <SelectField label="Student" value={form.student_id} onChange={e => setForm(p => ({...p, student_id: e.target.value}))} required
            options={students.map(s => ({ value: s.id, label: `${s.first_name} ${s.last_name} (${s.roll_no})` }))} />
          <InputField label="Title" value={form.title} onChange={e => setForm(p => ({...p, title: e.target.value}))} placeholder="e.g. Tuition Fee - September 2026" required />
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0 16px' }}>
            <InputField label="Amount (Rs.)" value={form.amount} onChange={e => setForm(p => ({...p, amount: e.target.value}))} type="number" required />
            <InputField label="Due Date" value={form.due_date} onChange={e => setForm(p => ({...p, due_date: e.target.value}))} type="date" required />
          </div>
          <InputField label="Month" value={form.month} onChange={e => setForm(p => ({...p, month: e.target.value}))} placeholder="e.g. September 2026" />
          <InputField label="Description" value={form.description} onChange={e => setForm(p => ({...p, description: e.target.value}))} placeholder="Additional details..." />
          <div style={{ display: 'flex', gap: 12, justifyContent: 'flex-end', marginTop: 8 }}>
            <Button variant="secondary" onClick={() => setShowCreate(false)}>Cancel</Button>
            <Button onClick={handleCreate} disabled={saving}>{saving ? 'Creating...' : 'Create Challan'}</Button>
          </div>
        </Modal>
      )}

      {/* Review Payment Modal */}
      {reviewingPayment && (
        <Modal title={`Review Payment: ${reviewingPayment.challan_no}`} onClose={() => setReviewingPayment(null)} width={560}>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12, marginBottom: 20 }}>
            {[
              ['Student', reviewingPayment.student ? `${reviewingPayment.student.first_name} ${reviewingPayment.student.last_name}` : '—'],
              ['Roll No', reviewingPayment.student?.roll_no || '—'],
              ['Amount', `Rs. ${Number(reviewingPayment.amount).toLocaleString()}`],
              ['Due Date', reviewingPayment.due_date],
              ['Payment Method', reviewingPayment.payment?.[0]?.payment_method?.toUpperCase()],
              ['Transaction ID', reviewingPayment.payment?.[0]?.transaction_id],
              ['Amount Paid', reviewingPayment.payment?.[0]?.amount_paid ? `Rs. ${Number(reviewingPayment.payment[0].amount_paid).toLocaleString()}` : '—'],
              ['Submitted At', reviewingPayment.payment?.[0]?.submitted_at ? new Date(reviewingPayment.payment[0].submitted_at).toLocaleString() : '—'],
            ].map(([l, v]) => (
              <div key={l}>
                <div style={{ fontSize: '0.7rem', color: 'rgba(255,255,255,0.4)', fontWeight: 600, textTransform: 'uppercase' }}>{l}</div>
                <div style={{ fontSize: '0.88rem', color: '#fff', marginTop: 2 }}>{v}</div>
              </div>
            ))}
          </div>
          {reviewingPayment.payment?.[0]?.screenshot_url && (
            <div style={{ marginBottom: 16 }}>
              <div style={{ fontSize: '0.75rem', fontWeight: 700, color: GOLD, marginBottom: 8 }}>Payment Screenshot</div>
              <div style={{ background: 'rgba(255,255,255,0.04)', borderRadius: 12, padding: 16, textAlign: 'center' }}>
                <img src={reviewingPayment.payment[0].screenshot_url} alt="Payment proof" style={{ maxWidth: '100%', maxHeight: 300, borderRadius: 8 }} />
              </div>
            </div>
          )}
          <div style={{ display: 'flex', gap: 12, justifyContent: 'flex-end' }}>
            <Button variant="danger" onClick={() => handleVerify('rejected')} disabled={saving}>Reject Payment</Button>
            <Button variant="success" onClick={() => handleVerify('approved')} disabled={saving}>Approve Payment</Button>
          </div>
        </Modal>
      )}
    </div>
  );
}

// ============================================================
// SECTION: GUARDIANS
// ============================================================
function GuardiansSection() {
  const [guardians, setGuardians] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => { db.getAllGuardians().then(data => { setGuardians(data); setLoading(false); }); }, []);

  const columns = [
    { key: 'name', label: 'Name', render: r => r.user ? `${r.user.first_name} ${r.user.last_name}` : '—' },
    { key: 'cnic', label: 'CNIC', render: r => r.user?.cnic, nowrap: true },
    { key: 'phone', label: 'Phone', render: r => r.user?.phone, nowrap: true },
    { key: 'email', label: 'Email', render: r => r.user?.email || '—' },
    { key: 'occupation', label: 'Occupation' },
    { key: 'relation_to_student', label: 'Relation' },
  ];

  return (
    <div>
      <SectionHeader title="Guardians" subtitle={`${guardians.length} registered guardians`} />
      {loading ? <div style={{ textAlign: 'center', padding: 40, color: 'rgba(255,255,255,0.3)' }}>Loading...</div> :
        <Table columns={columns} data={guardians} actions={row => (
          <>
            <ActionButton icon={Icons.eye(14)} title="View" color={GOLD} />
            <ActionButton icon={Icons.edit(14)} title="Edit" color="#3b82f6" />
          </>
        )} />
      }
    </div>
  );
}

// ============================================================
// SECTION: ANNOUNCEMENTS
// ============================================================
function AnnouncementsSection() {
  const [announcements, setAnnouncements] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showCreate, setShowCreate] = useState(false);
  const [form, setForm] = useState({ title: '', content: '', category: 'General', is_pinned: false });
  const [saving, setSaving] = useState(false);

  const load = async () => {
    setLoading(true);
    setAnnouncements(await db.getAllAnnouncements());
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  const handleCreate = async () => {
    setSaving(true);
    const user = getCurrentUser();
    await db.createAnnouncement({ ...form, created_by: user?.id, target_roles: ['admin', 'teacher', 'guardian'] });
    setShowCreate(false);
    setForm({ title: '', content: '', category: 'General', is_pinned: false });
    load();
    setSaving(false);
  };

  const handleDelete = async (id) => {
    await db.deleteAnnouncement(id);
    load();
  };

  return (
    <div>
      <SectionHeader title="Announcements" subtitle={`${announcements.length} announcements`} action={
        <Button onClick={() => setShowCreate(true)}>{Icons.plus(16)} New Announcement</Button>
      } />

      <div style={{ display: 'grid', gap: 12 }}>
        {loading ? <div style={{ textAlign: 'center', padding: 40, color: 'rgba(255,255,255,0.3)' }}>Loading...</div> :
          announcements.length === 0 ? <div style={{ textAlign: 'center', padding: 40, color: 'rgba(255,255,255,0.25)' }}>No announcements yet</div> :
          announcements.map(a => (
            <Card key={a.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 16 }}>
              <div style={{ flex: 1 }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6 }}>
                  <span style={{ fontWeight: 700, color: '#fff', fontSize: '0.95rem' }}>{a.title}</span>
                  {a.is_pinned && <Badge text="Pinned" color={GOLD} />}
                  <Badge text={a.category} color="#3b82f6" />
                </div>
                <p style={{ fontSize: '0.82rem', color: 'rgba(255,255,255,0.5)', lineHeight: 1.5, margin: 0 }}>{a.content}</p>
                <div style={{ fontSize: '0.72rem', color: 'rgba(255,255,255,0.25)', marginTop: 6 }}>
                  {new Date(a.created_at).toLocaleDateString()} &bull; {a.author ? `${a.author.first_name} ${a.author.last_name}` : 'System'}
                </div>
              </div>
              <div style={{ display: 'flex', gap: 6 }}>
                <ActionButton icon={Icons.trash(14)} title="Delete" color="#ef4444" onClick={() => handleDelete(a.id)} />
              </div>
            </Card>
          ))
        }
      </div>

      {showCreate && (
        <Modal title="Create Announcement" onClose={() => setShowCreate(false)}>
          <InputField label="Title" value={form.title} onChange={e => setForm(p => ({...p, title: e.target.value}))} required />
          <div style={{ marginBottom: 14 }}>
            <label style={{ display: 'block', fontSize: '0.78rem', color: 'rgba(255,255,255,0.5)', marginBottom: 6, fontWeight: 500 }}>Content <span style={{ color: '#ef4444' }}>*</span></label>
            <textarea value={form.content} onChange={e => setForm(p => ({...p, content: e.target.value}))} rows={4} style={{
              width: '100%', padding: '10px 14px', background: 'rgba(255,255,255,0.04)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 10, color: '#fff', fontSize: '0.85rem', outline: 'none', resize: 'vertical', fontFamily: 'inherit',
            }} />
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0 16px' }}>
            <SelectField label="Category" value={form.category} onChange={e => setForm(p => ({...p, category: e.target.value}))}
              options={['General', 'Academic', 'Meeting', 'Notice', 'Event', 'Urgent'].map(c => ({ value: c, label: c }))} />
            <div style={{ marginBottom: 14, display: 'flex', alignItems: 'flex-end', paddingBottom: 14 }}>
              <label style={{ display: 'flex', alignItems: 'center', gap: 8, cursor: 'pointer', fontSize: '0.85rem', color: '#fff' }}>
                <input type="checkbox" checked={form.is_pinned} onChange={e => setForm(p => ({...p, is_pinned: e.target.checked}))} style={{ accentColor: GOLD }} />
                Pin this announcement
              </label>
            </div>
          </div>
          <div style={{ display: 'flex', gap: 12, justifyContent: 'flex-end', marginTop: 8 }}>
            <Button variant="secondary" onClick={() => setShowCreate(false)}>Cancel</Button>
            <Button onClick={handleCreate} disabled={saving}>{saving ? 'Creating...' : 'Create Announcement'}</Button>
          </div>
        </Modal>
      )}
    </div>
  );
}

// ============================================================
// MAIN ADMIN PORTAL
// ============================================================
export default function AdminPortal() {
  const router = useRouter();
  const [user, setUser] = useState(null);
  const [activeSection, setActiveSection] = useState('dashboard');
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(false);

  useEffect(() => {
    const u = getCurrentUser();
    if (!u || u.role !== 'admin') {
      router.replace('/login');
      return;
    }
    setUser(u);
    const checkMobile = () => setIsMobile(window.innerWidth < 900);
    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  if (!user) return null;

  const renderSection = () => {
    switch (activeSection) {
      case 'dashboard': return <DashboardSection />;
      case 'teachers': return <TeachersSection />;
      case 'sessions': return <SessionsSection />;
      case 'students': return <StudentsSection />;
      case 'admissions': return <AdmissionsSection />;
      case 'challans': return <ChallansSection />;
      case 'guardians': return <GuardiansSection />;
      case 'announcements': return <AnnouncementsSection />;
      default: return <DashboardSection />;
    }
  };

  const handleNavClick = (id) => {
    setActiveSection(id);
    if (isMobile) setSidebarOpen(false);
  };

  // Sidebar content (shared desktop/mobile)
  const sidebarContent = (
    <>
      {/* Logo */}
      <div style={{ padding: '24px 20px 20px', display: 'flex', alignItems: 'center', gap: 12, borderBottom: '1px solid rgba(255,255,255,0.06)' }}>
        <img src="/faeq-logo.png" alt="Al-Faeq" style={{ width: 36, height: 36, borderRadius: 10, objectFit: 'cover' }} />
        <div>
          <div style={{ fontSize: '0.88rem', fontWeight: 800, color: '#fff', lineHeight: 1 }}>Al-Faeq</div>
          <div style={{ fontSize: '0.65rem', color: GOLD, fontWeight: 600, marginTop: 2 }}>Admin Panel</div>
        </div>
      </div>

      {/* Nav Items */}
      <nav style={{ padding: '12px 10px', flex: 1 }}>
        {NAV_ITEMS.map(item => {
          const isActive = activeSection === item.id;
          return (
            <button
              key={item.id}
              onClick={() => handleNavClick(item.id)}
              style={{
                display: 'flex', alignItems: 'center', gap: 12,
                width: '100%', padding: '11px 14px',
                background: isActive ? `${GOLD}12` : 'transparent',
                border: 'none', borderRadius: 12,
                cursor: 'pointer', marginBottom: 2,
                transition: 'all 0.2s ease',
                color: isActive ? GOLD : 'rgba(255,255,255,0.45)',
                fontSize: '0.84rem', fontWeight: isActive ? 700 : 500,
                textAlign: 'left',
                position: 'relative',
              }}
            >
              {isActive && <div style={{ position: 'absolute', left: 0, top: '20%', bottom: '20%', width: 3, borderRadius: 2, background: GOLD }} />}
              {item.icon(18, isActive ? GOLD : 'rgba(255,255,255,0.35)')}
              {item.label}
            </button>
          );
        })}
      </nav>

      {/* User & Logout */}
      <div style={{ padding: '16px 20px', borderTop: '1px solid rgba(255,255,255,0.06)' }}>
        <div style={{ fontSize: '0.82rem', fontWeight: 600, color: '#fff', marginBottom: 4 }}>{user.first_name} {user.last_name}</div>
        <div style={{ fontSize: '0.7rem', color: 'rgba(255,255,255,0.3)', marginBottom: 12 }}>{user.email}</div>
        <button onClick={() => { logout(); router.push('/login'); }} style={{
          display: 'flex', alignItems: 'center', gap: 8,
          width: '100%', padding: '10px 14px',
          background: 'rgba(239,68,68,0.08)', border: '1px solid rgba(239,68,68,0.15)',
          borderRadius: 12, cursor: 'pointer', color: '#fca5a5',
          fontSize: '0.82rem', fontWeight: 600, transition: 'all 0.2s',
        }}>
          {Icons.logout(16, '#fca5a5')} Sign Out
        </button>
      </div>
    </>
  );

  return (
    <>
      <Head>
        <title>Admin Panel — Al-Faeq Education System</title>
        <meta name="description" content="Al-Faeq Education System Admin Panel - Manage teachers, students, sessions, admissions, and challans" />
      </Head>

      <div style={{ display: 'flex', minHeight: '100vh', background: '#0a0e1a', fontFamily: "'Inter', sans-serif" }}>
        {/* Desktop Sidebar */}
        {!isMobile && (
          <aside style={{
            width: 260, minHeight: '100vh',
            background: 'rgba(255,255,255,0.02)',
            borderRight: '1px solid rgba(255,255,255,0.06)',
            display: 'flex', flexDirection: 'column',
            position: 'fixed', left: 0, top: 0, bottom: 0,
            zIndex: 100,
          }}>
            {sidebarContent}
          </aside>
        )}

        {/* Mobile overlay sidebar */}
        {isMobile && sidebarOpen && (
          <>
            <div onClick={() => setSidebarOpen(false)} style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.6)', backdropFilter: 'blur(4px)', zIndex: 998 }} />
            <aside style={{
              position: 'fixed', left: 0, top: 0, bottom: 0,
              width: 280, zIndex: 999,
              background: '#0f1322',
              borderRight: '1px solid rgba(255,255,255,0.08)',
              display: 'flex', flexDirection: 'column',
              animation: 'slideInRight 0.25s ease',
            }}>
              {sidebarContent}
            </aside>
          </>
        )}

        {/* Main Content */}
        <main style={{
          flex: 1,
          marginLeft: isMobile ? 0 : 260,
          minHeight: '100vh',
        }}>
          {/* Top Bar (mobile) */}
          {isMobile && (
            <div style={{
              display: 'flex', alignItems: 'center', justifyContent: 'space-between',
              padding: '14px 20px',
              background: 'rgba(255,255,255,0.02)',
              borderBottom: '1px solid rgba(255,255,255,0.06)',
              position: 'sticky', top: 0, zIndex: 50,
              backdropFilter: 'blur(12px)',
            }}>
              <button onClick={() => setSidebarOpen(true)} style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#fff', padding: 0 }}>
                {Icons.menu(24)}
              </button>
              <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                <img src="/faeq-logo.png" alt="" style={{ width: 28, height: 28, borderRadius: 8 }} />
                <span style={{ fontWeight: 700, fontSize: '0.92rem', color: '#fff' }}>Admin Panel</span>
              </div>
              <div style={{ width: 24 }} />
            </div>
          )}

          {/* Content Area */}
          <div style={{ padding: isMobile ? '20px 16px' : '32px 40px', maxWidth: 1200 }}>
            {/* Breadcrumb */}
            <div style={{ marginBottom: 24 }}>
              <div style={{ fontSize: '0.72rem', color: 'rgba(255,255,255,0.25)', fontWeight: 500, textTransform: 'uppercase', letterSpacing: '0.1em' }}>
                Admin Panel / {NAV_ITEMS.find(n => n.id === activeSection)?.label || 'Dashboard'}
              </div>
            </div>
            {renderSection()}
          </div>
        </main>
      </div>

      <style jsx>{`
        @keyframes slideInRight {
          from { transform: translateX(-100%); opacity: 0; }
          to { transform: translateX(0); opacity: 1; }
        }
        * { scrollbar-width: thin; scrollbar-color: rgba(255,255,255,0.1) transparent; }
        *::-webkit-scrollbar { width: 6px; }
        *::-webkit-scrollbar-track { background: transparent; }
        *::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); border-radius: 3px; }
        select option { background: #1a1f2e; color: #fff; }
      `}</style>
    </>
  );
}
